// src/components/FeeStructure.jsx
import React, { useEffect, useState } from "react";
import axios from "axios";

export default function FeeStructure() {
  const [fee, setFee] = useState(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    axios.get("http://localhost:5000/api/fees")
      .then(res => {
        setFee(res.data);
        setLoading(false);
      })
      .catch(err => {
        console.error(err);
        setLoading(false);
      });
  }, []);

  if (loading) return <p>Loading...</p>;
  if (!fee) return <p>No fee structure available.</p>;

  return (
    <div className="fee-structure-page">
      <h2>Fee Structure</h2>
      <p><strong>Total Fee:</strong> ₹{fee.totalFee}</p>
      <ul>
        <li>Admission Fee: ₹{fee.admissionFee}</li>
        <li>Tuition Fee: ₹{fee.tuitionFee}</li>
        <li>Transport Fee: ₹{fee.transportFee}</li>
        <li>Miscellaneous: ₹{fee.miscellaneous}</li>
      </ul>
      <div dangerouslySetInnerHTML={{ __html: fee.aboutFee }} />
    </div>
  );
}
